<?php $pageTitle=htmlspecialchars((string)$combo['title']).' — Combo Offer'; include INCLUDE_PATH.'/partials/head.php'; include INCLUDE_PATH.'/partials/header.php'; $saving=max(0,(float)$combo['regular_price']-(float)$combo['combo_price']); ?>
<main class="combo-detail-page"><div class="container"><nav class="combo-breadcrumb"><a href="/">Home</a><span>›</span><span>Combo Offers</span></nav><section class="combo-detail-hero"><div class="combo-detail-image"><img src="<?= htmlspecialchars((string)$combo['banner_image']) ?>" alt="<?= htmlspecialchars((string)$combo['title']) ?>"></div><div class="combo-detail-copy"><?php if($combo['badge']):?><span><?= htmlspecialchars((string)$combo['badge']) ?></span><?php endif;?><h1><?= htmlspecialchars((string)$combo['title']) ?></h1><p><?= nl2br(htmlspecialchars((string)($combo['description']?:$combo['short_description']))) ?></p><div class="combo-prices"><del>₹<?= number_format((float)$combo['regular_price']) ?></del><strong>₹<?= number_format((float)$combo['combo_price']) ?></strong><?php if($saving>0):?><b>Save ₹<?= number_format($saving) ?> (<?= number_format((float)($combo['discount_percent']??0),2) ?>%)</b><?php endif;?></div><button class="btn btn-orange" id="addComboBtn" onclick="addComboToCart()">Add Combo to Cart</button><div id="comboCartMsg"></div></div></section><section class="combo-products"><h2>What's included</h2><div><?php foreach($combo['items'] as $item):?><article><img src="<?= htmlspecialchars((string)($item['product_image']?:'/assets/images/RCS%20PRINT%20LOGO.png')) ?>" alt="<?= htmlspecialchars((string)$item['product_name']) ?>"><h3><?= htmlspecialchars((string)$item['product_name']) ?></h3><p>Quantity: <?= number_format((int)$item['quantity']) ?></p><strong>₹<?= number_format((float)$item['regular_price']) ?></strong></article><?php endforeach;?><?php foreach(($combo['custom_items']??[]) as $item):?><article><img src="<?= htmlspecialchars((string)($item['thumbnail_path']?:'/assets/images/RCS%20PRINT%20LOGO.png')) ?>" alt="<?= htmlspecialchars((string)$item['item_name']) ?>"><h3><?= htmlspecialchars((string)$item['item_name']) ?></h3><p>Custom combo item</p><strong>₹<?= number_format((float)$item['item_price']) ?></strong></article><?php endforeach;?></div></section></div></main><script>async function addComboToCart(){const b=document.getElementById('addComboBtn');b.disabled=true;const r=await fetch('/api/cart/combo',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':APP.csrfToken},credentials:'same-origin',body:JSON.stringify({combo_offer_id:<?= (int)$combo['id'] ?>})}).then(r=>r.json()).catch(()=>({ok:false,msg:'Could not add combo'}));if(r.ok)location.href='/cart';else{document.getElementById('comboCartMsg').textContent=r.msg||'Could not add combo';b.disabled=false;}}</script>
